package com.example.newselfverifyingapp.domain.model

/**
 * Candidate solution generated by the AI model executed in the Docker sandbox.
 * Follows the authoritative specification from Live Verification & Candidate Comparison.
 */
data class CandidateResult(
    val candidateId: String,          // e.g., "C1", "C2", "C3"
    val code: String,                 // Python solution source code
    val durationMs: Long,             // Execution runtime in milliseconds
    val passedTests: Int,             // Raw count of visible tests passed
    val totalTests: Int,              // Total visible tests evaluated
    val isSelected: Boolean = false,  // Selected by highest visible pass count (ties go to first)
    val selectionNote: String = "",   // e.g., "first of tie", "tied · not chosen", "AssertionError"
    val errorMessage: String? = null  // e.g., "test 3 · AssertionError" if test failed
)
